import { authorizedSuccessionChapterMedia } from './successionChapterMedia.generated.js';
import {
  SUCCESSION_BANK_END,
  SUCCESSION_BANK_START,
  successionChapterBankByNumber,
  successionChapterBankRecords,
} from './successionChapterBank.js';

export const SUCCESSION_READER_START = SUCCESSION_BANK_START;
export const SUCCESSION_READER_END = SUCCESSION_BANK_END;

// Page records are generated by the chapter import tools, normalized by the
// Chapter Bank, and consumed by the public reader in stored reading order.
export { authorizedSuccessionChapterMedia };

export const successionChapterReaderRecords = Object.freeze(
  successionChapterBankRecords.map((record) => Object.freeze({
    chapter: record.chapter,
    label: record.label,
    pages: record.pages,
    pageCount: record.pageCount,
    mediaStatus: record.pageCount ? 'local-media' : 'awaiting-local-media',
    bankStatus: record.status,
    missingPages: record.missingPages,
    lastUpdated: record.lastUpdated,
  })),
);

export const successionChapterReaderByNumber = new Map(
  successionChapterReaderRecords.map((record) => [record.chapter, record]),
);

export const successionChapterBankRecordByNumber = successionChapterBankByNumber;
export const SUCCESSION_READER_TOTAL = successionChapterReaderRecords.length;
